EXECUTE cloudflow_schema_stmt;
DEALLOCATE PREPARE cloudflow_schema_stmt;
SET @cloudflow_schema_sql = IF(EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='oa_meeting_minutes' AND column_name='schedule_event_id'), 'SELECT 1', 'ALTER TABLE oa_meeting_minutes ADD COLUMN schedule_event_id BIGINT(20) DEFAULT NULL AFTER organizer_name');
