INSERT IGNORE INTO cloud_flow_db.sys_role_menu (role_id,menu_id,tenant_id)
SELECT r.role_id,m.menu_id,r.tenant_id FROM cloud_flow_db.sys_role r CROSS JOIN cloud_flow_db.sys_menu m WHERE r.tenant_id BETWEEN 100000 AND 100049 AND r.role_key='admin' AND r.status='0' AND r.deleted=0 AND m.status='0' AND m.menu_id NOT BETWEEN 3000 AND 3049 AND m.menu_id NOT BETWEEN 1970 AND 1976 AND m.menu_id NOT BETWEEN 1780 AND 1799 AND m.menu_id NOT IN (1987,1988);
INSERT IGNORE INTO cloud_flow_db.sys_role_menu (role_id,menu_id,tenant_id)
SELECT r.role_id,m.menu_id,r.tenant_id FROM cloud_flow_db.sys_role r CROSS JOIN cloud_flow_db.sys_menu m WHERE r.tenant_id BETWEEN 100000 AND 100049 AND r.role_key='hr' AND r.status='0' AND r.deleted=0 AND m.status='0' AND (m.menu_id IN (6,1756,1757) OR m.menu_id BETWEEN 1320 AND 1324);
INSERT IGNORE INTO cloud_flow_db.sys_role_menu (role_id,menu_id,tenant_id)
SELECT r.role_id,m.menu_id,r.tenant_id FROM cloud_flow_db.sys_role r CROSS JOIN cloud_flow_db.sys_menu m WHERE r.tenant_id BETWEEN 100000 AND 100049 AND r.status='0' AND r.deleted=0 AND m.menu_id IN (1325,1336,1337,1338,1339);
