INSERT INTO cloud_flow_db.hr_recruitment_identity (tenant_id, identity_type, identity_hash, candidate_id, create_by, update_by)
SELECT candidate.tenant_id, 'EMAIL', SHA2(CONCAT(candidate.tenant_id, ':EMAIL:', LOWER(TRIM(candidate.email))), 256), candidate.id, 'seed', 'seed' FROM cloud_flow_db.hr_candidate candidate WHERE candidate.tenant_id BETWEEN 100000 AND 100049 AND candidate.email IS NOT NULL AND TRIM(candidate.email) <> '' AND NOT EXISTS (SELECT 1 FROM cloud_flow_db.hr_recruitment_identity identity_row WHERE identity_row.tenant_id = candidate.tenant_id AND identity_row.identity_type = 'EMAIL' AND identity_row.identity_hash = SHA2(CONCAT(candidate.tenant_id, ':EMAIL:', LOWER(TRIM(candidate.email))), 256));
